<?php
require_once __DIR__.'/includes/functions.php'; exigir_tipo(['gerente','funcionario']); $titulo='Lançamentos'; $erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $conta=trim($_POST['conta']??'');$tipo=$_POST['tipo']??'';$valor=str_replace(',','.',trim($_POST['valor']??'0'));
 if(!conta_ativa($conta))$erro='Conta não encontrada ou não está ativa.';
 elseif(!in_array($tipo,['D','S'],true))$erro='Tipo de lançamento inválido.';
 elseif(!is_numeric($valor)||(float)$valor<=0)$erro='Informe um valor maior que zero.';
 elseif($tipo==='S' && saldo_conta($conta)<(float)$valor)$erro='Saldo insuficiente para realizar o saque.';
 else {$stmt=mysqli_prepare($conexao,'SELECT agencia FROM tbcontas WHERE conta=? LIMIT 1');mysqli_stmt_bind_param($stmt,'s',$conta);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);$dados=mysqli_fetch_assoc($r);mysqli_stmt_close($stmt);$agencia=$dados['agencia'];$data=date('Y-m-d');$valorFloat=(float)$valor;$stmt=mysqli_prepare($conexao,'INSERT INTO tblancamentos (conta, agencia, data_lanc, valor, tipo) VALUES (?, ?, ?, ?, ?)');mysqli_stmt_bind_param($stmt,'sssds',$conta,$agencia,$data,$valorFloat,$tipo);if(mysqli_stmt_execute($stmt)){$_SESSION['mensagem']=$tipo==='D'?'Depósito realizado com sucesso.':'Saque realizado com sucesso.';redirecionar('lancamentos.php');}$erro='Não foi possível registrar o lançamento.';mysqli_stmt_close($stmt);}
}
$ultimos=mysqli_query($conexao,'SELECT l.conta,l.agencia,l.data_lanc,l.valor,l.tipo,c.cliente FROM tblancamentos l LEFT JOIN tbcontas c ON c.conta=l.conta ORDER BY l.data_lanc DESC LIMIT 15');include __DIR__.'/includes/header.php'; ?>
<div class="cabecalho-pagina"><div><span class="etiqueta">MOVIMENTAÇÃO</span><h1>Lançamentos</h1><p>Registre depósitos e saques de contas ativas.</p></div></div><?php if($erro): ?><div class="alerta"><?=e($erro)?></div><?php endif; ?><section class="painel"><h2>Novo lançamento</h2><form method="post" autocomplete="off"><div class="form-grade"><div><label>Número da conta</label><input name="conta" maxlength="10" required></div><div><label>Tipo de lançamento</label><select name="tipo"><option value="D">Depósito</option><option value="S">Saque</option></select></div><div><label>Valor (R$)</label><input name="valor" type="number" min="0.01" step="0.01" required></div></div><p class="dica">O sistema verifica se a conta está ativa e se há saldo suficiente para saques.</p><button class="botao botao-principal">Confirmar lançamento</button></form></section><section class="painel margem-topo"><h2>Movimentações recentes</h2><div class="tabela-responsiva"><table><thead><tr><th>Data</th><th>Conta</th><th>Cliente</th><th>Tipo</th><th>Valor</th></tr></thead><tbody><?php if($ultimos):while($l=mysqli_fetch_assoc($ultimos)): ?><tr><td><?=e(date('d/m/Y',strtotime($l['data_lanc'])))?></td><td><?=e($l['conta'])?></td><td><?=e($l['cliente']??'—')?></td><td><span class="status <?=$l['tipo']==='D'?'status-ok':'status-off'?>"><?=$l['tipo']==='D'?'Depósito':'Saque'?></span></td><td><?=dinheiro($l['valor'])?></td></tr><?php endwhile;endif; ?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php'; ?>
